"""Container With Most Water — two pointers from the outside in.

The width only shrinks, so the only way to beat the current area is a taller
line: move the shorter side inward and never revisit it.

Time: O(n)   Space: O(1)
"""
from typing import List


class Solution:
    def maxArea(self, height: List[int]) -> int:
        lo, hi, best = 0, len(height) - 1, 0
        while lo < hi:
            best = max(best, (hi - lo) * min(height[lo], height[hi]))
            if height[lo] < height[hi]:
                lo += 1
            else:
                hi -= 1
        return best
